package reality_test

// Precision claims of the numerical packages: linalg, optim and its
// subpackages, calculus and chaos. The cases live in
// testdata/stress/precision_numerics.json, generated by
// tools/stressgolden/numerics.py (mpmath at 60 digits); each case states how
// it reads the doc comment it checks. The ratchet itself is
// TestPrecisionClaims in precision_test.go.
//
// For a vector or matrix result an evaluator returns one error measure, named
// in the case's claim, and the case expects 0. A function that reports failure
// where its doc comment promises a result is scored as NaN (a miss), and a
// promised failure (nil, false) that does not happen scores 1 against 0.

import (
	"errors"
	"fmt"
	"math"
	"math/big"

	"github.com/davly/reality/calculus"
	"github.com/davly/reality/chaos"
	"github.com/davly/reality/linalg"
	"github.com/davly/reality/optim"
	"github.com/davly/reality/optim/hrp"
	"github.com/davly/reality/optim/portfolio"
	"github.com/davly/reality/optim/proximal"
	"github.com/davly/reality/optim/transport"
)

func numVec(c precisionCase, k string) []float64 {
	raw, ok := c.Args[k].([]any)
	if !ok {
		panic(fmt.Sprintf("%s: argument %q is not an array", c.ID, k))
	}
	v := make([]float64, len(raw))
	for i, x := range raw {
		f, ok := x.(float64)
		if !ok {
			panic(fmt.Sprintf("%s: argument %q[%d] is not a number", c.ID, k, i))
		}
		v[i] = f
	}
	return v
}

func numMat(c precisionCase, k string) [][]float64 {
	raw, ok := c.Args[k].([]any)
	if !ok {
		panic(fmt.Sprintf("%s: argument %q is not an array", c.ID, k))
	}
	m := make([][]float64, len(raw))
	for i, r := range raw {
		row, ok := r.([]any)
		if !ok {
			panic(fmt.Sprintf("%s: argument %q[%d] is not an array", c.ID, k, i))
		}
		m[i] = make([]float64, len(row))
		for j, x := range row {
			f, ok := x.(float64)
			if !ok {
				panic(fmt.Sprintf("%s: argument %q[%d][%d] is not a number", c.ID, k, i, j))
			}
			m[i][j] = f
		}
	}
	return m
}

func numInts(c precisionCase, k string) []int {
	v := numVec(c, k)
	out := make([]int, len(v))
	for i, x := range v {
		if x != math.Trunc(x) {
			panic(fmt.Sprintf("%s: argument %q[%d] is not an integer", c.ID, k, i))
		}
		out[i] = int(x)
	}
	return out
}

func numStr(c precisionCase, k string) string {
	s, ok := c.Args[k].(string)
	if !ok {
		panic(fmt.Sprintf("%s: argument %q is not a string", c.ID, k))
	}
	return s
}

// numNormwiseErr returns max_i |got_i - want_i| / max_i |want_i|.
func numNormwiseErr(got, want []float64) float64 {
	if len(got) != len(want) {
		return math.Inf(1)
	}
	var e, m float64
	for i := range want {
		d := math.Abs(got[i] - want[i])
		if math.IsNaN(d) {
			return math.Inf(1)
		}
		e = math.Max(e, d)
		m = math.Max(m, math.Abs(want[i]))
	}
	if m == 0 {
		return e
	}
	return e / m
}

// numMaxAbsErr returns max_i |got_i - want_i|.
func numMaxAbsErr(got, want []float64) float64 {
	if len(got) != len(want) {
		return math.Inf(1)
	}
	var e float64
	for i := range want {
		d := math.Abs(got[i] - want[i])
		if math.IsNaN(d) {
			return math.Inf(1)
		}
		e = math.Max(e, d)
	}
	return e
}

// numExactNorm2 returns the 2-norm of v, accumulated exactly in big.Float and
// rounded once at the end, so the measure adds no error of its own beyond
// that final rounding.
func numExactNorm2(v []float64) float64 {
	const prec = 4096
	sum := new(big.Float).SetPrec(prec)
	for _, x := range v {
		if math.IsNaN(x) || math.IsInf(x, 0) {
			return math.NaN()
		}
		t := new(big.Float).SetPrec(prec).SetFloat64(x)
		sum.Add(sum, t.Mul(t, t))
	}
	f, _ := new(big.Float).SetPrec(prec).Sqrt(sum).Float64()
	return f
}

// numMaxRelErr returns max_i |got_i - want_i| / |want_i| (absolute where
// want_i is 0); a missing result is +Inf.
func numMaxRelErr(got, want []float64) float64 {
	if len(got) != len(want) {
		return math.Inf(1)
	}
	var e float64
	for i := range want {
		d := math.Abs(got[i] - want[i])
		if want[i] != 0 {
			d /= math.Abs(want[i])
		}
		if math.IsNaN(d) {
			return math.Inf(1)
		}
		e = math.Max(e, d)
	}
	return e
}

// numSumMinusOne returns sum(v) - 1, with the sum taken exactly.
func numSumMinusOne(v []float64) float64 { return numSumMinus(v, 1) }

// numSumMinus returns sum(v) - t, computed exactly and rounded once.
func numSumMinus(v []float64, t float64) float64 {
	const prec = 4096
	sum := new(big.Float).SetPrec(prec).SetFloat64(-t)
	for _, x := range v {
		if math.IsNaN(x) || math.IsInf(x, 0) {
			return math.NaN()
		}
		sum.Add(sum, new(big.Float).SetPrec(prec).SetFloat64(x))
	}
	f, _ := sum.Float64()
	return f
}

func numFlatten(m [][]float64) []float64 {
	var out []float64
	for _, r := range m {
		out = append(out, r...)
	}
	return out
}

func numBool(b bool) float64 {
	if b {
		return 1
	}
	return 0
}

func init() {
	registerLinalgEvaluators()
	registerOptimEvaluators()
	registerPortfolioEvaluators()
	registerProxTransportEvaluators()
	registerCalculusChaosEvaluators()
	registerKnownPrecisionViolations(numericsKnownViolations)
}

