func registerLinalgEvaluators() {
	registerPrecisionEvaluator("linalg.PearsonCorrelation", func(c precisionCase) (float64, error) {
		return linalg.PearsonCorrelation(numVec(c, "x"), numVec(c, "y")), nil
	})
	registerPrecisionEvaluator("linalg.SpearmanCorrelation", func(c precisionCase) (float64, error) {
		return linalg.SpearmanCorrelation(numVec(c, "x"), numVec(c, "y")), nil
	})
	registerPrecisionEvaluator("linalg.Trace", func(c precisionCase) (float64, error) {
		return linalg.Trace(numVec(c, "A"), argI(c, "n")), nil
	})
	registerPrecisionEvaluator("linalg.CrossProduct", func(c precisionCase) (float64, error) {
		out := make([]float64, 3)
		linalg.CrossProduct(numVec(c, "a"), numVec(c, "b"), out)
		return numNormwiseErr(out, numVec(c, "truth")), nil
	})
	registerPrecisionEvaluator("linalg.JamesSteinShrink", func(c precisionCase) (float64, error) {
		_, shrink := linalg.JamesSteinShrink(numVec(c, "means"), argF(c, "variance"))
		return shrink, nil
	})
	lw := func(f func([]float64, int, int) ([]float64, float64)) func(precisionCase) (float64, error) {
		return func(c precisionCase) (float64, error) {
			sigma, intensity := f(numVec(c, "x"), argI(c, "T"), argI(c, "N"))
			switch numStr(c, "measure") {
			case "intensity":
				return intensity, nil
			case "matrix":
				return numNormwiseErr(sigma, numVec(c, "truth")), nil
			}
			return 0, fmt.Errorf("unknown measure %q", numStr(c, "measure"))
		}
	}
	registerPrecisionEvaluator("linalg.LedoitWolfShrinkageIdentity", lw(linalg.LedoitWolfShrinkageIdentity))
	registerPrecisionEvaluator("linalg.LedoitWolfShrinkageConstantCorr", lw(linalg.LedoitWolfShrinkageConstantCorr))
	registerPrecisionEvaluator("linalg.MarchenkoPasturBounds", func(c precisionCase) (float64, error) {
		lo, hi := linalg.MarchenkoPasturBounds(argF(c, "q"))
		if numStr(c, "which") == "min" {
			return lo, nil
		}
		return hi, nil
	})
	registerPrecisionEvaluator("linalg.CleanCorrelation", func(c precisionCase) (float64, error) {
		out := linalg.CleanCorrelation(numVec(c, "corr"), argI(c, "T"), argI(c, "N"))
		return numMaxAbsErr(out, numVec(c, "truth")), nil
	})
	registerPrecisionEvaluator("linalg.L2Norm", func(c precisionCase) (float64, error) {
		return linalg.L2Norm(numVec(c, "v")), nil
	})
	registerPrecisionEvaluator("linalg.EncodingDistance", func(c precisionCase) (float64, error) {
		return linalg.EncodingDistance(numVec(c, "a"), numVec(c, "b")), nil
	})
	registerPrecisionEvaluator("linalg.DimensionWeightedDistance", func(c precisionCase) (float64, error) {
		return linalg.DimensionWeightedDistance(numVec(c, "a"), numVec(c, "b"), numVec(c, "w")), nil
	})
	registerPrecisionEvaluator("linalg.L2Normalize", func(c precisionCase) (float64, error) {
		v := numVec(c, "v")
		linalg.L2Normalize(v)
		return numExactNorm2(v), nil
	})
	registerPrecisionEvaluator("linalg.CosineSimilarity", func(c precisionCase) (float64, error) {
		return linalg.CosineSimilarity(numVec(c, "a"), numVec(c, "b")), nil
	})
	registerPrecisionEvaluator("linalg.DotProduct", func(c precisionCase) (float64, error) {
		return linalg.DotProduct(numVec(c, "a"), numVec(c, "b")), nil
	})
	registerPrecisionEvaluator("linalg.L1Norm", func(c precisionCase) (float64, error) {
		return linalg.L1Norm(numVec(c, "v")), nil
	})
	registerPrecisionEvaluator("linalg.LInfNorm", func(c precisionCase) (float64, error) {
		return linalg.LInfNorm(numVec(c, "v")), nil
	})
	registerPrecisionEvaluator("linalg.Determinant", func(c precisionCase) (float64, error) {
		return linalg.Determinant(numVec(c, "A"), argI(c, "n")), nil
	})
	registerPrecisionEvaluator("linalg.Inverse", func(c precisionCase) (float64, error) {
		n := argI(c, "n")
		out := make([]float64, n*n)
		return numBool(linalg.Inverse(numVec(c, "A"), n, out)), nil
	})
}

// The test functions below are written so that the Go compiler cannot fuse
// their multiply-adds (an explicit float64 conversion rounds the product), so
// each is the same function on every build; only the code under test differs
// between builds.

var numFuncs1D = map[string]func(float64) float64{
	"exp":         math.Exp,
	"sin":         math.Sin,
	"x2minus2":    func(x float64) float64 { return float64(x*x) - 2 },
	"expminus1e5": func(x float64) float64 { return math.Exp(x) - 1e5 },
	"sq_xminus2": func(x float64) float64 {
		d := x - 2
		return float64(d * d)
	},
	"sq_xminus1_plus1": func(x float64) float64 {
		d := x - 1
		return float64(d*d) + 1
	},
	"cosh_xminus0.3": func(x float64) float64 { return math.Cosh(x - 0.3) },
	"sq_xminus1e6_plus1": func(x float64) float64 {
		d := x - 1e6
		return float64(d*d) + 1
	},
}

func numFunc1D(c precisionCase) func(float64) float64 {
	f, ok := numFuncs1D[numStr(c, "f")]
	if !ok {
		panic(fmt.Sprintf("%s: unknown function %q", c.ID, numStr(c, "f")))
	}
	return f
}

type numBudgetExceeded struct{}

// numWithBudget runs search with f wrapped to allow at most budget calls. A
// search still running after budget calls has not met its claimed iteration
// count (or never terminates); it is stopped by a panic and scored as NaN.
func numWithBudget(f func(float64) float64, budget int, search func(func(float64) float64) float64) (got float64) {
	calls := 0
	counted := func(x float64) float64 {
		calls++
		if calls > budget {
			panic(numBudgetExceeded{})
		}
		return f(x)
	}
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(numBudgetExceeded); !ok {
				panic(r)
			}
			got = math.NaN()
		}
	}()
	return search(counted)
}

func numRosenbrock(x []float64) float64 {
	a := 1 - x[0]
	b := x[1] - float64(x[0]*x[0])
	return float64(a*a) + float64(100*float64(b*b))
}

func numRosenbrockGrad(x, g []float64) {
	b := x[1] - float64(x[0]*x[0])
	g[0] = float64(-2*(1-x[0])) - float64(float64(400*x[0])*b)
	g[1] = float64(200 * b)
}

func registerOptimEvaluators() {
	registerPrecisionEvaluator("optim.LBFGS", func(c precisionCase) (float64, error) {
		var f func([]float64) float64
		var grad func([]float64, []float64)
		switch numStr(c, "problem") {
		case "rosenbrock":
			f, grad = numRosenbrock, numRosenbrockGrad
		case "quadratic":
			A, b := numVec(c, "A"), numVec(c, "b")
			n := len(b)
			ax := func(x []float64, out []float64) {
				for i := 0; i < n; i++ {
					s := 0.0
					for j := 0; j < n; j++ {
						s += float64(A[i*n+j] * x[j])
					}
					out[i] = s
				}
			}
			f = func(x []float64) float64 {
				t := make([]float64, n)
				ax(x, t)
				s := 0.0
				for i := range x {
					s += float64(x[i] * float64(0.5*t[i]-b[i]))
				}
				return s
			}
			grad = func(x, g []float64) {
				ax(x, g)
				for i := range g {
					g[i] -= b[i]
				}
			}
		default:
			return 0, fmt.Errorf("unknown problem %q", numStr(c, "problem"))
		}
		x := optim.LBFGS(f, grad, numVec(c, "x0"), argI(c, "m"), argI(c, "maxIter"), argF(c, "tol"))
		return numMaxAbsErr(x, numVec(c, "truth")), nil
	})
	registerPrecisionEvaluator("optim.BisectionMethod", func(c precisionCase) (float64, error) {
		a, b, tol := argF(c, "a"), argF(c, "b"), argF(c, "tol")
		return numWithBudget(numFunc1D(c), argI(c, "budget"), func(f func(float64) float64) float64 {
			return optim.BisectionMethod(f, a, b, tol)
		}), nil
	})
	registerPrecisionEvaluator("optim.GoldenSectionSearch", func(c precisionCase) (float64, error) {
		a, b, tol := argF(c, "a"), argF(c, "b"), argF(c, "tol")
		return numWithBudget(numFunc1D(c), argI(c, "budget"), func(f func(float64) float64) float64 {
			return optim.GoldenSectionSearch(f, a, b, tol)
		}), nil
	})
	registerPrecisionEvaluator("optim.LinearInterpolate", func(c precisionCase) (float64, error) {
		return optim.LinearInterpolate(argF(c, "x0"), argF(c, "y0"), argF(c, "x1"), argF(c, "y1"), argF(c, "x")), nil
	})
	registerPrecisionEvaluator("optim.LinearInterpolateRoot", func(c precisionCase) (float64, error) {
		return optim.LinearInterpolateRoot(argF(c, "x0"), argF(c, "y0"), argF(c, "x1"), argF(c, "y1")), nil
	})
	registerPrecisionEvaluator("optim.SimplexMethod", func(c precisionCase) (float64, error) {
		cost, flat, b := numVec(c, "c"), numVec(c, "A"), numVec(c, "b")
		m, n := argI(c, "m"), len(cost)
		A := make([][]float64, m)
		for i := range A {
			A[i] = flat[i*n : (i+1)*n]
		}
		_, val, err := optim.SimplexMethod(cost, A, b)
		if err != nil {
			return math.NaN(), nil
		}
		return val, nil
	})
}

func registerPortfolioEvaluators() {
	registerPrecisionEvaluator("portfolio.ImpliedEquilibriumReturns", func(c precisionCase) (float64, error) {
		pi := portfolio.ImpliedEquilibriumReturns(numVec(c, "w"), numMat(c, "Sigma"), argF(c, "delta"))
		return numMaxRelErr(pi, numVec(c, "truth")), nil
	})
	registerPrecisionEvaluator("portfolio.RoundTrip", func(c precisionCase) (float64, error) {
		w, sigma, delta := numVec(c, "w"), numMat(c, "Sigma"), argF(c, "delta")
		back := portfolio.MeanVarianceWeights(portfolio.ImpliedEquilibriumReturns(w, sigma, delta), sigma, delta)
		return numNormwiseErr(back, w), nil
	})
	registerPrecisionEvaluator("portfolio.HeLittermanOmega", func(c precisionCase) (float64, error) {
		om := portfolio.HeLittermanOmega(numMat(c, "P"), numMat(c, "Sigma"), argF(c, "tau"))
		if om == nil {
			return math.NaN(), nil
		}
		return om[0][0], nil
	})
	registerPrecisionEvaluator("portfolio.BlackLittermanPosterior", func(c precisionCase) (float64, error) {
		mu := portfolio.BlackLittermanPosterior(numVec(c, "pi"), numMat(c, "Sigma"), numMat(c, "P"), numVec(c, "Q"), numMat(c, "Omega"), argF(c, "tau"))
		if m, ok := c.Args["measure"]; ok && m == "returned" {
			return numBool(mu != nil), nil
		}
		return numMaxRelErr(mu, numVec(c, "truth")), nil
	})
	registerPrecisionEvaluator("portfolio.BlackLittermanPosteriorCovariance", func(c precisionCase) (float64, error) {
		m := portfolio.BlackLittermanPosteriorCovariance(numMat(c, "Sigma"), numMat(c, "P"), numMat(c, "Omega"), argF(c, "tau"))
		return numNormwiseErr(numFlatten(m), numVec(c, "truth")), nil
	})
	weights := func(f func([]float64, [][]float64, float64) []float64) func(precisionCase) (float64, error) {
		return func(c precisionCase) (float64, error) {
			w := f(numVec(c, "mu"), numMat(c, "Sigma"), argF(c, "param"))
			switch numStr(c, "measure") {
			case "returned":
				return numBool(w != nil), nil
			case "relerr":
				return numMaxRelErr(w, numVec(c, "truth")), nil
			}
			return 0, fmt.Errorf("unknown measure %q", numStr(c, "measure"))
		}
	}
	registerPrecisionEvaluator("portfolio.MeanVarianceWeights", weights(portfolio.MeanVarianceWeights))
	registerPrecisionEvaluator("portfolio.ContinuousKellyWeights", weights(portfolio.ContinuousKellyWeights))
	registerPrecisionEvaluator("portfolio.MeanVarianceWeightsLongOnly", func(c precisionCase) (float64, error) {
		w := portfolio.MeanVarianceWeightsLongOnly(numVec(c, "mu"), numMat(c, "Sigma"), argF(c, "delta"))
		return numMaxAbsErr(w, numVec(c, "truth")), nil
	})
	registerPrecisionEvaluator("portfolio.ProjectSimplex", func(c precisionCase) (float64, error) {
		w := portfolio.ProjectSimplex(numVec(c, "v"))
		switch numStr(c, "measure") {
		case "weights":
			return numMaxAbsErr(w, numVec(c, "truth")), nil
		case "sum":
			return math.Abs(numSumMinusOne(w)), nil
		}
		return 0, fmt.Errorf("unknown measure %q", numStr(c, "measure"))
	})
	registerPrecisionEvaluator("hrp.CorrelationDistance", func(c precisionCase) (float64, error) {
		rho := argF(c, "rho")
		d, err := hrp.CorrelationDistance([][]float64{{1, rho}, {rho, 1}})
		if err != nil {
			return 0, err
		}
		return d[0][1], nil
	})
	registerPrecisionEvaluator("hrp.RecursiveBisection", func(c precisionCase) (float64, error) {
		w, err := hrp.RecursiveBisection(numMat(c, "cov"), numInts(c, "order"))
		if err != nil {
			return 0, err
		}
		return math.Abs(numSumMinusOne(w)), nil
	})
}

func registerProxTransportEvaluators() {
	registerPrecisionEvaluator("proximal.Fbs", func(c precisionCase) (float64, error) {
		A, b := numVec(c, "A"), numVec(c, "b")
		m := argI(c, "m")
		n := len(A) / m
		lambda := argF(c, "lambda")
		accel, ok := c.Args["accelerate"].(bool)
		if !ok {
			return 0, fmt.Errorf("accelerate is not a boolean")
		}
		residual := func(x []float64) []float64 {
			r := make([]float64, m)
			for i := 0; i < m; i++ {
				s := -b[i]
				for j := 0; j < n; j++ {
					s += float64(A[i*n+j] * x[j])
				}
				r[i] = s
			}
			return r
		}
		grad := func(x, out []float64) float64 {
			r := residual(x)
			for j := 0; j < n; j++ {
				s := 0.0
				for i := 0; i < m; i++ {
					s += float64(A[i*n+j] * r[i])
				}
				out[j] = s
			}
			return 0
		}
		prox := func(v []float64, gamma float64, out []float64) { proximal.ProxL1(v, gamma*lambda, out) }
		x := make([]float64, n)
		work := make([]float64, n)
		cfg := proximal.FbsConfig{Step: argF(c, "step"), MaxIter: argI(c, "iters"), AbsTol: 1e-300, Accelerate: accel}
		if _, err := proximal.Fbs(grad, prox, x, work, cfg); err != nil {
			return 0, err
		}
		obj := 0.0
		for _, ri := range residual(x) {
			obj += float64(ri * ri)
		}
		obj /= 2
		for _, xi := range x {
			obj += float64(lambda * math.Abs(xi))
		}
		return obj - argF(c, "fstar"), nil
	})
	registerPrecisionEvaluator("transport.Sinkhorn", func(c precisionCase) (float64, error) {
		a, b, cost, eps := numVec(c, "a"), numVec(c, "b"), numMat(c, "cost"), argF(c, "epsilon")
		switch numStr(c, "measure") {
		case "default-budget":
			_, err := transport.Sinkhorn(a, b, cost, eps, 0, 0)
			if err == nil {
				return 0, nil
			}
			if !errors.Is(err, transport.ErrSinkhornNonConvergent) {
				return 0, err
			}
			res, err := transport.Sinkhorn(a, b, cost, eps, 1000, 0)
			if err != nil {
				return math.Inf(1), nil
			}
			return float64(res.Iterations - 200), nil
		case "row-residual":
			res, err := transport.Sinkhorn(a, b, cost, eps, argI(c, "maxIter"), argF(c, "tol"))
			if err != nil {
				return math.NaN(), nil
			}
			total := 0.0
			for i, row := range res.Plan {
				total += math.Abs(numSumMinus(row, a[i]))
			}
			return total, nil
		}
		return 0, fmt.Errorf("unknown measure %q", numStr(c, "measure"))
	})
	registerPrecisionEvaluator("transport.Wasserstein1D", func(c precisionCase) (float64, error) {
		return transport.Wasserstein1D(numVec(c, "u"), numVec(c, "v"), argF(c, "p"))
	})
}

func registerCalculusChaosEvaluators() {
	registerPrecisionEvaluator("calculus.NumericalDerivative", func(c precisionCase) (float64, error) {
		return calculus.NumericalDerivative(numFunc1D(c), argF(c, "x"), argF(c, "h")), nil
	})
	registerPrecisionEvaluator("calculus.NumericalGradient", func(c precisionCase) (float64, error) {
		if numStr(c, "f") != "exp2d" {
			return 0, fmt.Errorf("unknown function %q", numStr(c, "f"))
		}
		f := func(x []float64) float64 { return math.Exp(x[0]) + math.Exp(2*x[1]) }
		x := numVec(c, "x")
		out := make([]float64, len(x))
		calculus.NumericalGradient(f, x, argF(c, "h"), out)
		truth, bound := numVec(c, "truth"), numVec(c, "bound")
		worst := 0.0
		for i := range out {
			worst = math.Max(worst, math.Abs(out[i]-truth[i])/bound[i])
		}
		return worst, nil
	})
	registerPrecisionEvaluator("calculus.TrapezoidalRule", func(c precisionCase) (float64, error) {
		return calculus.TrapezoidalRule(numFunc1D(c), argF(c, "a"), argF(c, "b"), argI(c, "n")), nil
	})
	registerPrecisionEvaluator("calculus.SimpsonsRule", func(c precisionCase) (float64, error) {
		return calculus.SimpsonsRule(numFunc1D(c), argF(c, "a"), argF(c, "b"), argI(c, "n")), nil
	})
	registerPrecisionEvaluator("calculus.GaussLegendre", func(c precisionCase) (float64, error) {
		coef := numVec(c, "coef")
		poly := func(x float64) float64 {
			acc := 0.0
			for _, k := range coef {
				acc = float64(acc*x) + k
			}
			return acc
		}
		return calculus.GaussLegendre(poly, argF(c, "a"), argF(c, "b"), argI(c, "points")), nil
	})
	registerPrecisionEvaluator("chaos.EulerStep", func(c precisionCase) (float64, error) {
		out := make([]float64, 1)
		chaos.EulerStep(func(_ float64, y, dydt []float64) { dydt[0] = y[0] }, 0, []float64{1}, argF(c, "dt"), out)
		return out[0], nil
	})
	registerPrecisionEvaluator("chaos.LogisticMap", func(c precisionCase) (float64, error) {
		r, x := argF(c, "r"), argF(c, "x0")
		for i := argI(c, "iters"); i > 0; i-- {
			x = chaos.LogisticMap(r, x)
		}
		return x, nil
	})
}
